import{_ as e,o as t,c as l,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const d=JSON.parse('{"title":"迪克·西蒙斯","description":"","frontmatter":{"title":"迪克·西蒙斯","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/迪克·西蒙斯.md","filePath":"04_people/迪克·西蒙斯.md"}'),o={name:"04_people/迪克·西蒙斯.md"};function i(s,a,n,_,h,p){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="迪克·西蒙斯" tabindex="-1">迪克·西蒙斯 <a class="header-anchor" href="#迪克·西蒙斯" aria-label="Permalink to &quot;迪克·西蒙斯&quot;">​</a></h1><ul><li><strong>角色职位</strong>：华盛顿邮报管理层，水牛城新闻（Buffalo News）管理者</li><li><strong>与巴菲特关系</strong>：受巴菲特委托管理伯克希尔旗下媒体资产的管理者</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>迪克·西蒙斯是伯克希尔·哈撒韦旗下水牛城新闻（The Buffalo News）的重要管理者。水牛城新闻是伯克希尔旗下历史悠久的报纸资产，巴菲特对该报有着深厚的个人感情。1977年，巴菲特收购了水牛城新闻，此后该报一直在伯克希尔的媒体资产组合中占据重要地位。</p><p>西蒙斯在水牛城新闻的管理中发挥了重要作用。他负责报纸的日常运营，包括编辑方针、发行管理、广告销售等各个方面。在他的管理下，水牛城新闻保持了良好的财务状况和内容质量，成为当地市场的主要媒体力量。他与巴菲特保持着良好的沟通，严格执行巴菲特对媒体业务的经营理念。</p><p>迪克·西蒙斯的管理工作体现了伯克希尔&quot;无为而治&quot;的管理哲学——优秀的本地管理者被充分授权，在日常运营中享有高度自主权，同时对经营结果负责。这种管理模式使得水牛城新闻在竞争日益激烈的报纸行业中保持了相对稳定的盈利能力。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1977年</strong>：巴菲特收购水牛城新闻，西蒙斯此后担任该报管理层</li><li><strong>1980-1990年代</strong>：管理水牛城新闻日常运营，维持报纸市场地位</li><li><strong>1990年代以后</strong>：继续在水牛城新闻担任管理职务，确保资产稳健经营</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/03_companies/水牛城新闻.html">1977年：完整翻译|/01_letters/1977年/翻译</a></li><li><a href="/03_companies/水牛城新闻.html">1979年：完整翻译|/01_letters/1979年/翻译</a></li><li><a href="/03_companies/水牛城新闻.html">1988年：完整翻译|/01_letters/1988年/翻译</a></li></ul>',11)])])}const u=e(o,[["render",i]]);export{d as __pageData,u as default};
